-- Party bots phase 2 (#65): spell rotations per spec, generated by tools/partybot/gen_partybot_spells.py.
-- Tune here or in the generator; read by the worldserver at start (restart to apply). Undo: DROP TABLE world.partybot_spells.
CREATE TABLE IF NOT EXISTS world.partybot_spells (spec SMALLINT UNSIGNED NOT NULL, prio TINYINT UNSIGNED NOT NULL,
  spell INT UNSIGNED NOT NULL, type VARCHAR(16) NOT NULL, param INT NOT NULL DEFAULT 0, aura INT UNSIGNED NOT NULL DEFAULT 0,
  comment VARCHAR(64) NOT NULL DEFAULT '', PRIMARY KEY (spec, prio)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM world.partybot_spells;
-- talent builds (undo: DROP TABLE world.partybot_talents)
CREATE TABLE IF NOT EXISTS world.partybot_talents (spec SMALLINT UNSIGNED NOT NULL, talent INT UNSIGNED NOT NULL,
  PRIMARY KEY (spec, talent)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM world.partybot_talents;
